"""Runs inside the synthetic UC-08/Public Identity fixture; no live accounts."""
check(sql("select 'security_invoker=true'=any(reloptions) from pg_class where oid='public.public_profiles'::regclass")=='t','view has security_invoker true')
check(auth('', 'select count(*) from public.public_profiles')=='0','missing authenticated identity sees no public identity')
r=sql('begin;set local role anon;select * from public.public_profiles;rollback',False)
check(r.returncode!=0 and '42501' in r.stderr,'anonymous view SELECT remains denied')
check(auth(A,f"select count(*) from public.public_profiles where id='{A}'")=='1','active self profile visible through invoker view')
check(auth(B,f"select count(*) from public.public_profiles where id='{A}'")=='0','authorized counterpart direct view access is now self-only')
check(auth(A,f"select count(*) from public.public_profiles where id='{U}'")=='0','unrelated private profile remains inaccessible')
check(auth(A,f"select count(*) from public.profiles where id<>'{A}'")=='0','underlying own-row RLS unchanged')
sql(f"update profiles set public_nickname='Public Alias',public_nickname_confirmed_at=now(),avatar_path='{A}/public/{uid(970)}.jpg',avatar_public_confirmed_at=now() where id='{A}'")
check(auth(A,f"select display_name from public.public_profiles where id='{A}'")=='Public Alias','self view keeps consented nickname')
identity=json.loads(auth(B,f"select get_public_identities(array['{A}']::uuid[])"))[0]
check(identity['nickname']=='Public Alias' and identity['avatar_path']==f'{A}/public/{uid(970)}.jpg','protected RPC preserves cross-user nickname/avatar access')
check(set(identity)=={'id','nickname','avatar_path'},'cross-user RPC exposes only existing approved fields')
check(json.loads(auth(A,f"select get_public_identities(array['{U}']::uuid[])"))==[],'unrelated identity RPC read remains denied')
check(json.loads(auth(B,f"select get_messaging_inbox(0,20,'{cid}')"))[0]['participant_name']=='Public Alias','definer inbox keeps gated counterpart identity through invoker view')
check(auth(A,"select count(*) from public.public_profiles where bio is not null or trust_score is not null or trust_badge is not null or created_at is not null")=='0','sanitized private columns remain null')
after=sql("select jsonb_build_object('policies',(select jsonb_agg(to_jsonb(p) order by tablename,policyname) from pg_policies p),'functions',(select jsonb_agg(jsonb_build_array(oid::regprocedure::text,pg_get_functiondef(oid),proacl::text) order by oid) from pg_proc where pronamespace='public'::regnamespace),'acl',(select relacl::text from pg_class where oid='public.public_profiles'::regclass))::text")
check(after==invoker_before,'migration changes no policy, function implementation/ACL or view grant')
load(root/'supabase/test-support/public_profiles_security_invoker_rollback.sql')
check(auth(B,f"select display_name from public.public_profiles where id='{A}'")=='Public Alias','emergency rollback restores prior gated view compatibility')
load(next((root/'supabase/migrations').glob('*_public_profiles_security_invoker.sql')))
check(auth(B,f"select count(*) from public.public_profiles where id='{A}'")=='0','reapplication restores direct self-only view')
check(json.loads(auth(B,f"select get_public_identities(array['{A}']::uuid[])"))[0]['nickname']=='Public Alias','rollback/reapplication never changes protected public identity RPC')
